// paramtips.js — catalog-grounded hover documentation for geometry parameters. AGPL-3.0-or-later.
//
// P9 ask 1 (owner): whenever a geometry parameter appears in the GUI, hovering it must say what
// it does — grounded in the generated parameter catalog, never invented. The catalog
// (gui/static/param-catalog.v1.json, generated by tools/gen_param_catalog.py from
// design/params/ + its authorities) is served by the EXISTING static handler — no new route,
// same relative-asset convention as app.js itself. Mechanism: the glossary.js::tip precedent
// (native `title` on a keyboard-focusable .term span).
//
// Every lookup degrades gracefully to the raw key: a network failure, a missing/unknown
// typology or an unknown key NEVER breaks a page — the tooltip just shows the raw name, as
// before this module existed.
//
// Lookup is per config name (the catalog is keyed by the resolved typology's config name).
// Knob names are overloaded across typologies (n, q, a_deg, T, … give one key DIFFERENT
// meanings in different families), so an unknown config name falls back to the raw key rather
// than guessing another typology's meaning. Nested seed/bounds paths (profileH.points.1.1)
// fall back to their parent path up to the base knob's own entry.

import { fmt } from "./charts.js";      // the repo's own number formatting (2 decimals, en-US)

// ── catalog cache ──────────────────────────────────────────────────────────────────

let CACHE = null;

/** Load (and cache) the parameter catalog. Never throws, never rejects: any failure leaves
 *  the cache unset and every lookup falls back to the raw key. `opts.data` injects a catalog
 *  object directly (offline node tests); without it the module fetches the static asset by the
 *  same relative convention the page's own JS assets use. A failed network load is not cached,
 *  so the next view open retries. */
export async function loadParamCatalog(opts = {}) {
  if (opts && opts.data !== undefined) {
    CACHE = (opts.data && typeof opts.data === "object" && opts.data.typologies &&
             typeof opts.data.typologies === "object") ? opts.data : null;
    return CACHE;
  }
  if (CACHE) return CACHE;
  try {
    const r = await fetch("param-catalog.v1.json");
    if (!r.ok) return CACHE;                            // missing file -> raw-key fallback
    const cat = await r.json();
    if (cat && typeof cat === "object" && cat.typologies && typeof cat.typologies === "object")
      CACHE = cat;
  } catch { /* network failure / bad JSON -> raw-key fallback */ }
  return CACHE;
}

/** The catalog entry for one config name, or null. Never a cross-typology guess. */
function catalogEntry(configName) {
  if (!CACHE || !configName || typeof configName !== "string") return null;
  const t = CACHE.typologies[configName];
  return (t && typeof t === "object") ? t : null;
}

// ── lookups ────────────────────────────────────────────────────────────────────────

/** The doc for one (config name, key): the knob entry the catalog carries for the exact
 *  seed/bounds key, with a nested-path fallback (profileH.points.1.1 → profileH.points.1 →
 *  profileH — the base knob's entry). Returns null when the config, the key or the catalog is
 *  unknown — callers must handle null by showing the raw key. Pure over the cache. */
export function docFor(configName, key) {
  const t = catalogEntry(configName);
  const knobs = t && Array.isArray(t.knobs) ? t.knobs : null;
  if (!knobs || typeof key !== "string" || !key) return null;
  for (const d of knobs) if (d && d.knob === key) return d;
  if (key.includes(".")) {
    let k = key;
    while (k.includes(".")) {
      k = k.slice(0, k.lastIndexOf("."));               // step up to the base knob's entry
      for (const d of knobs) if (d && d.knob === k) return d;
    }
  }
  return null;
}

// ── pure formatters (node-testable without a DOM) ──────────────────────────────────

/** `Search range 600.00..1,200.00 Hz.` — second sentence of a tooltip. "" when the doc carries
 *  no usable search bounds. Numbers go through the repo's own formatter (charts.js::fmt). */
export function formatSearchRange(doc) {
  const s = (doc && typeof doc === "object") ? doc.search : null;
  if (!s || typeof s !== "object") return "";
  if (s.lo == null || s.hi == null || !isFinite(Number(s.lo)) || !isFinite(Number(s.hi))) return "";
  const unit = (doc.unit != null && doc.unit !== "") ? " " + doc.unit : "";
  return `Search range ${fmt(s.lo)}..${fmt(s.hi)}${unit}.`;
}

/** The tooltip title for a knob doc, same sentence shape as glossary.js::tip()
 *  (`label [unit]: summary`) plus the search-range second sentence, capped so titles stay
 *  readable. When the visible text is NOT the raw key (a label override), the raw key is kept
 *  in the title as `label [unit] (raw_key): summary…` — the key is never lost entirely. */
export function formatParamTitle(doc, key, labelOverride) {
  if (!doc || typeof doc !== "object") return null;
  const label = doc.label != null && doc.label !== "" ? String(doc.label) : "";
  const unit = doc.unit != null && doc.unit !== "" ? String(doc.unit) : "";
  const summary = doc.summary != null && doc.summary !== "" ? String(doc.summary) : "";
  if (!label && !summary) return null;
  const head = `${label}${unit ? " [" + unit + "]" : ""}`;
  const showKey = labelOverride != null && labelOverride !== "" && labelOverride !== key;
  const keyed = `${head}${showKey ? " (" + key + ")" : ""}`;
  const range = formatSearchRange(doc);
  const full = head && summary ? `${keyed}: ${summary}${range ? " " + range : ""}`
    : head ? (range ? `${keyed}: ${range}` : keyed)
    : `${summary}${summary && range ? " " : ""}${range}`;     // labelless doc: the words carry it
  return full.length > 300 ? full.slice(0, 297) + "…" : full;
}

// ── HTML builders (the glossary.js::tip precedent: native title on a focusable .term) ──

const escHtml = s => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#39;");

/** Tooltip-wrapped label HTML for one parameter: `<span class="term" tabindex="0" title="…">…</span>`.
 *  Visible text: the labelOverride when given (the sites that show the raw key pass it here),
 *  else the catalog's label, else the raw key. Graceful fallback (no doc): the raw key as both
 *  text and title — exactly the pre-catalog behaviour, never a blank cell. */
export function paramTipHtml(configName, key, labelOverride) {
  const doc = docFor(configName, key);
  const visible = (labelOverride != null && labelOverride !== "") ? labelOverride
    : (doc && doc.label != null && doc.label !== "" ? doc.label : (key ?? ""));
  // the visible text decides: only when it is NOT the raw key must the title carry the key
  const title = formatParamTitle(doc, key, visible) ?? String(key ?? "");
  return `<span class="term" tabindex="0" title="${escHtml(title)}">${escHtml(visible)}</span>`;
}

/** Just the assembled title text for one parameter (sites that own their markup, e.g. the
 *  evolution knob rows), or null when the catalog has nothing — callers fall back to the raw key. */
export function paramTitle(configName, key) {
  return formatParamTitle(docFor(configName, key), key, null);
}

// ── typology-card surface ──────────────────────────────────────────────────────────

/** The searched-parameter count the catalog records for a typology (what the card displays as
 *  "N shape parameters"), or null. */
function searchedCount(t) {
  const bi = t && t.bounds_index && typeof t.bounds_index === "object" ? t.bounds_index : null;
  if (!bi) return null;
  return Object.keys(bi).filter(k => bi[k] && bi[k].search !== false).length;
}

/** Hover HTML for a typology NAME: the catalog's typology-level description plus the knob
 *  count, or the API's own description when the catalog lacks the typology. "" when neither
 *  exists (the raw name renders instead — callers keep their template). */
export function typologyTipHtml(t) {
  const name = t && t.name != null && t.name !== "" ? String(t.name) : "";
  if (!name) return "";
  const cat = catalogEntry(name);
  const desc = (cat && cat.description != null && cat.description !== "" ? String(cat.description)
    : (t && t.description != null && t.description !== "" ? String(t.description) : ""));
  const n = t && t.n_knobs != null ? t.n_knobs : searchedCount(cat);
  const parts = [];
  if (desc) parts.push(desc);
  if (n != null) parts.push(`${n} shape parameters`);
  const title = parts.length ? parts.join(" · ") : name;
  const capped = title.length > 300 ? title.slice(0, 297) + "…" : title;
  return `<span class="term" tabindex="0" title="${escHtml(capped)}">${escHtml(name)}</span>`;
}

/** Small mono chips of a typology's actual searched parameter keys (the card's knob NAMES),
 *  each with its enriched tooltip. "" when the catalog has no chips for this typology
 *  (unknown typology, or none searched — e.g. multicell_3x3) so nothing renders. */
export function typologyChipsHtml(configName) {
  const t = catalogEntry(configName);
  if (!t) return "";
  const n = searchedCount(t);
  if (!n) return "";
  const bi = t.bounds_index;
  const keys = Object.keys(bi).filter(k => bi[k] && bi[k].search !== false);
  if (!keys.length) return "";
  return `<div class="typ-knobs" aria-label="searched shape parameters">` +
    keys.map(k => `<span class="term typ-knob" tabindex="0" title="${escHtml(paramTitle(configName, k) ?? String(k))}">${escHtml(k)}</span>`).join("") +
    `</div>`;
}